-- 329: 大和オハナ保育園の「全体的な計画」(新規)と「保育安全計画」を令和8年度(2026年度)版で反映(俊指示 2026-08-25)。
-- 添付Excel(全体的な計画 H30改訂版 / 09_保育安全計画)の内容を guidance_plans.content(JSONB)に投入。
--   ・全体的な計画(plan_type='overall'): 大和は未投入だったため新規seed(既存あればcontent更新)。
--   ・保育安全計画(plan_type='safety'): 303の内容を今年度Excelで更新。
-- 安全計画の編集判断(俊確認): 点検7月は現行の正しい内容(園庭全体…固定遊具、排水路等)を維持、
--   誤字「渡たる→渡る」「てを→手を」を修正。バス車内置き去り防止・プール時対応の追記等はExcelどおり反映。
do $$
declare
  v_office uuid := 'c0a7010a-fd37-4cad-971b-6b3f2e80f842';
  v_year   int  := 2026;
  v_tmpl   uuid;
  v_id     uuid;
begin
  ------------------------------------------------------------------ 全体的な計画 (overall)
  select id into v_tmpl from guidance_plan_templates where plan_type='overall' and version=1;
  if v_tmpl is null then raise exception 'overall template not found (286未適用?)'; end if;
  select id into v_id from guidance_plans
    where office_id=v_office and plan_type='overall' and fiscal_year=v_year
      and class_id is null and month is null and week_start_date is null;
  if v_id is null then
    insert into guidance_plans (office_id, class_id, plan_type, age_variant, template_id, fiscal_year, content, status)
    values (v_office, null, 'overall', null, v_tmpl, v_year, '{"principle": "子ども達が一人の人格として尊重され現在を最も良く生きるために、保育園と保護者、地域全体が共に手を取り合い安全で安心できる環境をつくり、子どもの最善の利益を考え創意工夫を図る。", "direction": "人と人との関わりを大切に遊びを通して多くの事を体験させ、一人ひとりの気持ちを大切にたくさんの愛情で受け止め豊かな人間性を育んでいく。", "aim": "おもいやりのあるやさしいこころ\nはじめてをたのしむこころ\nなにごとにもぜんりょくのこころ", "responsibility": "人権に配慮する。子どもの人格を尊重し保育を行う。地域社会との交流や連携を図り、保育の内容を適切に説明する。個人情報を適切に取り扱う。保護者の苦情解決を図るよう努める。", "human_right": "人権に配慮し、子どもの人格を尊重し保育を行う", "accountability": "地域社会との交流や連携を図り、保育の内容を適切に説明する。", "information_protection": "入所する子ども等の個人情報を適切に取り扱う", "complaint_handling": "個人情報を保護し苦情解決責任者、または第三者委員を配置し苦情解決に取り組む", "aim*age0": "十分に養護の行き届いた環境で安心して過ごす。", "aim*age1": "自分でしようとする気持ちを尊重し温かく見守る。", "aim*age2": "一人一人の成長と集団としての活動の充実を図る。", "aim*age3": "人と関わる生活の中で人に対する愛情と信頼感を育てる。", "aim*age4": "生活の中で言葉への興味や関心を育て、表現する豊かさを養う。", "aim*age5": "様々な体験を通して豊かな感性や表現力を育み意欲的に活動する。", "life*age0": "一人一人の生活リズムが整うように配慮する。", "life*age1": "特定の保育士との信頼関係が更に深まり愛着関係が育まれるように接する。", "life*age2": "生活や遊びの中で、自我が育つような関わりを持つ。", "life*age3": "基本的な生活習慣を身につけられるよう援助する。", "life*age4": "子供の発達過程等に応じて適度な運動と休息を取ることができるようにする。", "life*age5": "健康に関心を持ち、生活に必要な習慣を身につけられるようにする。", "emotion*age0": "発達過程などを明確にし、応答的な触れ合いや、言葉かけを行う。", "emotion*age1": "スキンシップにより、保育士との関わりの心地よさや安心感を得るように接する。", "emotion*age2": "子供の気持ちを受容し、共感しながら断続的な信頼関係を築いていく。", "emotion*age3": "主体的な活動を促す環境を構成し探索意欲が高められるように見守る。", "emotion*age4": "多様な経験を通し自己肯定感を育み、自信や保育士への信頼を獲得できるようにする。", "emotion*age5": "生活リズムに応じた活動内容の調和を図り、適切な食事や休息が取れるようにする。", "healthygrow*age0": "食事や睡眠時間の生活リズムが芽生える", "withfeelings*age0": "特定の大人との深い関わりによる愛着心の形成", "sensitivity*age0": "身近なものと関わり感性が育つ", "health*age1": "・身の回りの簡単な事を自分でしようとする気持ちが芽生える", "health*age2": "生活の中で援助してもらいながら、自分でしようとする", "health*age3": "・身の回りを清潔にし、生活に必要な活動を自分でしようとする", "health*age4": "・身の回りを清潔にし、生活に必要な活動を自分でしようとする", "health*age5": "・室内外の危険な物や場所、危険な行動を知り気を付けて活動をする", "relations*age1": "・保育士や友だちに関心を持ち、真似をしたりして自ら関わろうとする", "relations*age2": "生活や遊びの中で順番を待つなどの決まりがある事を知る", "relations*age3": "友だちと簡単なルールのある遊びをする中でルールを守る", "relations*age4": "友だちと簡単なルールのある遊びをする中でルールを守る", "relations*age5": "高齢者を始め地域の人々など自分の生活に関係の深いいろいろな人に親しみを持つ", "environment*age1": "好きな玩具や遊具に興味を持って関わり様々な遊びを楽しむ", "environment*age2": "自然と触れ合う中で好奇心や探究心が生まれてくる", "environment*age3": "身近な動植物に親しみを持ち世話をすることで生命の尊さに気づく", "environment*age4": "身近な動植物に親しみを持ち世話をすることで生命の尊さに気づく", "environment*age5": "生活や遊びの中で簡単な標識や文字などに関心を持つ", "lang*age1": "親しみを持って、日常の挨拶をする", "lang*age2": "生活や遊びの中で簡単な言葉でのやり取りを楽しむ", "lang*age3": "友だちの話を聞いたり保育士に質問したり、興味を持った言葉によるイメージを楽しむ", "lang*age4": "友だちの話を聞いたり保育士に質問したり、興味を持った言葉によるイメージを楽しむ", "lang*age5": "人の話を聞いたり身近な文字に触れたりして言葉への興味を広げる", "expression*age1": "保育士と一緒に歌ったり手遊びをしたりリズムに合わせて体を動かして遊ぶ", "expression*age2": "保育士や友だちと遊ぶ中で自分なりのイメージを膨らませ楽しんで遊ぶ", "expression*age3": "色々な素材や用具に親しみ友だちと工夫して遊ぶ", "expression*age4": "色々な素材や用具に親しみ友だちと工夫して遊ぶ", "expression*age5": "自分のイメージを動き、言葉などで表現したり演じて遊ぶ楽しさを味わう", "mealeducation*age0": "食への興味を持つ。", "mealeducation*age1": "保育者と一緒に楽しく食べる", "mealeducation*age2": "発達段階に応じ咀嚼を知る。", "mealeducation*age3": "食事のマナーを知る。三大栄養素について知る。", "mealeducation*age4": "食事のマナーを知る。三大栄養素について知る。", "mealeducation*age5": "食事のマナーを知る。三大栄養素について知り理解する。", "health_care": "・健康発育状態の把握   ・心身状態や家庭生活、養育状態の把握  ・内科、歯科検診  ・異常が見られた時の対応", "environment_management": "施設の温度、湿度、換気、採光、音などの環境を常に適切な状況に保持するよう努めるとともに子ども及び全職員が清潔を保つようにする。また職員は衛生管理に努めること。", "accident_prevention": "安全対策のため全職員の共通理解や体制作りを図る。\n環境設定の見直し  ・玩具、遊具の点検", "guardian_support": "日常の保育に関連した様々な機会を活用し子どもの日々の様子の伝達や収集、保育所保育の意図の説明などを通じて、保護者との相互理解を図るよう努める。", "local_support": "保育所における通常業務である保育に支障をきたさない範囲で情報提供と相談及び助言を行う。", "local_event": "地域文作品出展", "training_plan": "・園内研修\n・園外研修への計画的な参加", "school_cooperation": "小学校以降の生活や学習の基盤の育成につながることを配慮するとともに『幼児期の終わりまでに育って欲しい姿』を共有し子どもの育ちを支えるための資料を送付する。", "self_evaluation": "保育所の評価・保育士等の自己評価・専門機関による第三者評価"}'::jsonb, 'draft');
  else
    update guidance_plans set content='{"principle": "子ども達が一人の人格として尊重され現在を最も良く生きるために、保育園と保護者、地域全体が共に手を取り合い安全で安心できる環境をつくり、子どもの最善の利益を考え創意工夫を図る。", "direction": "人と人との関わりを大切に遊びを通して多くの事を体験させ、一人ひとりの気持ちを大切にたくさんの愛情で受け止め豊かな人間性を育んでいく。", "aim": "おもいやりのあるやさしいこころ\nはじめてをたのしむこころ\nなにごとにもぜんりょくのこころ", "responsibility": "人権に配慮する。子どもの人格を尊重し保育を行う。地域社会との交流や連携を図り、保育の内容を適切に説明する。個人情報を適切に取り扱う。保護者の苦情解決を図るよう努める。", "human_right": "人権に配慮し、子どもの人格を尊重し保育を行う", "accountability": "地域社会との交流や連携を図り、保育の内容を適切に説明する。", "information_protection": "入所する子ども等の個人情報を適切に取り扱う", "complaint_handling": "個人情報を保護し苦情解決責任者、または第三者委員を配置し苦情解決に取り組む", "aim*age0": "十分に養護の行き届いた環境で安心して過ごす。", "aim*age1": "自分でしようとする気持ちを尊重し温かく見守る。", "aim*age2": "一人一人の成長と集団としての活動の充実を図る。", "aim*age3": "人と関わる生活の中で人に対する愛情と信頼感を育てる。", "aim*age4": "生活の中で言葉への興味や関心を育て、表現する豊かさを養う。", "aim*age5": "様々な体験を通して豊かな感性や表現力を育み意欲的に活動する。", "life*age0": "一人一人の生活リズムが整うように配慮する。", "life*age1": "特定の保育士との信頼関係が更に深まり愛着関係が育まれるように接する。", "life*age2": "生活や遊びの中で、自我が育つような関わりを持つ。", "life*age3": "基本的な生活習慣を身につけられるよう援助する。", "life*age4": "子供の発達過程等に応じて適度な運動と休息を取ることができるようにする。", "life*age5": "健康に関心を持ち、生活に必要な習慣を身につけられるようにする。", "emotion*age0": "発達過程などを明確にし、応答的な触れ合いや、言葉かけを行う。", "emotion*age1": "スキンシップにより、保育士との関わりの心地よさや安心感を得るように接する。", "emotion*age2": "子供の気持ちを受容し、共感しながら断続的な信頼関係を築いていく。", "emotion*age3": "主体的な活動を促す環境を構成し探索意欲が高められるように見守る。", "emotion*age4": "多様な経験を通し自己肯定感を育み、自信や保育士への信頼を獲得できるようにする。", "emotion*age5": "生活リズムに応じた活動内容の調和を図り、適切な食事や休息が取れるようにする。", "healthygrow*age0": "食事や睡眠時間の生活リズムが芽生える", "withfeelings*age0": "特定の大人との深い関わりによる愛着心の形成", "sensitivity*age0": "身近なものと関わり感性が育つ", "health*age1": "・身の回りの簡単な事を自分でしようとする気持ちが芽生える", "health*age2": "生活の中で援助してもらいながら、自分でしようとする", "health*age3": "・身の回りを清潔にし、生活に必要な活動を自分でしようとする", "health*age4": "・身の回りを清潔にし、生活に必要な活動を自分でしようとする", "health*age5": "・室内外の危険な物や場所、危険な行動を知り気を付けて活動をする", "relations*age1": "・保育士や友だちに関心を持ち、真似をしたりして自ら関わろうとする", "relations*age2": "生活や遊びの中で順番を待つなどの決まりがある事を知る", "relations*age3": "友だちと簡単なルールのある遊びをする中でルールを守る", "relations*age4": "友だちと簡単なルールのある遊びをする中でルールを守る", "relations*age5": "高齢者を始め地域の人々など自分の生活に関係の深いいろいろな人に親しみを持つ", "environment*age1": "好きな玩具や遊具に興味を持って関わり様々な遊びを楽しむ", "environment*age2": "自然と触れ合う中で好奇心や探究心が生まれてくる", "environment*age3": "身近な動植物に親しみを持ち世話をすることで生命の尊さに気づく", "environment*age4": "身近な動植物に親しみを持ち世話をすることで生命の尊さに気づく", "environment*age5": "生活や遊びの中で簡単な標識や文字などに関心を持つ", "lang*age1": "親しみを持って、日常の挨拶をする", "lang*age2": "生活や遊びの中で簡単な言葉でのやり取りを楽しむ", "lang*age3": "友だちの話を聞いたり保育士に質問したり、興味を持った言葉によるイメージを楽しむ", "lang*age4": "友だちの話を聞いたり保育士に質問したり、興味を持った言葉によるイメージを楽しむ", "lang*age5": "人の話を聞いたり身近な文字に触れたりして言葉への興味を広げる", "expression*age1": "保育士と一緒に歌ったり手遊びをしたりリズムに合わせて体を動かして遊ぶ", "expression*age2": "保育士や友だちと遊ぶ中で自分なりのイメージを膨らませ楽しんで遊ぶ", "expression*age3": "色々な素材や用具に親しみ友だちと工夫して遊ぶ", "expression*age4": "色々な素材や用具に親しみ友だちと工夫して遊ぶ", "expression*age5": "自分のイメージを動き、言葉などで表現したり演じて遊ぶ楽しさを味わう", "mealeducation*age0": "食への興味を持つ。", "mealeducation*age1": "保育者と一緒に楽しく食べる", "mealeducation*age2": "発達段階に応じ咀嚼を知る。", "mealeducation*age3": "食事のマナーを知る。三大栄養素について知る。", "mealeducation*age4": "食事のマナーを知る。三大栄養素について知る。", "mealeducation*age5": "食事のマナーを知る。三大栄養素について知り理解する。", "health_care": "・健康発育状態の把握   ・心身状態や家庭生活、養育状態の把握  ・内科、歯科検診  ・異常が見られた時の対応", "environment_management": "施設の温度、湿度、換気、採光、音などの環境を常に適切な状況に保持するよう努めるとともに子ども及び全職員が清潔を保つようにする。また職員は衛生管理に努めること。", "accident_prevention": "安全対策のため全職員の共通理解や体制作りを図る。\n環境設定の見直し  ・玩具、遊具の点検", "guardian_support": "日常の保育に関連した様々な機会を活用し子どもの日々の様子の伝達や収集、保育所保育の意図の説明などを通じて、保護者との相互理解を図るよう努める。", "local_support": "保育所における通常業務である保育に支障をきたさない範囲で情報提供と相談及び助言を行う。", "local_event": "地域文作品出展", "training_plan": "・園内研修\n・園外研修への計画的な参加", "school_cooperation": "小学校以降の生活や学習の基盤の育成につながることを配慮するとともに『幼児期の終わりまでに育って欲しい姿』を共有し子どもの育ちを支えるための資料を送付する。", "self_evaluation": "保育所の評価・保育士等の自己評価・専門機関による第三者評価"}'::jsonb where id=v_id;
  end if;

  ------------------------------------------------------------------ 保育安全計画 (safety)
  select id into v_tmpl from guidance_plan_templates where plan_type='safety' and version=1;
  if v_tmpl is null then raise exception 'safety template not found (301未適用?)'; end if;
  select id into v_id from guidance_plans
    where office_id=v_office and plan_type='safety' and fiscal_year=v_year
      and class_id is null and month is null and week_start_date is null;
  if v_id is null then
    insert into guidance_plans (office_id, class_id, plan_type, age_variant, template_id, fiscal_year, content, status)
    values (v_office, null, 'safety', null, v_tmpl, v_year, '{"inspect_m4": "・防火設備\n・避難経路\n・緊急連絡先", "inspect_m5": "・遊具\n・散歩コース（散歩コース内の固定遊具を含む。）", "inspect_m6": "・プール用具の安全点検", "inspect_m7": "・園庭全体（内扉、フェンス、固定遊具、排水路等）\n・園舎全体（水道、トイレ、建付け、高所等）", "inspect_m8": "・加湿器\n・空気清浄機", "inspect_m9": "・台風対策\n（備蓄の確認等）", "inspect_m10": "園外保育の危険か所の点検\n園外保育での歩き方の指導", "inspect_m11": "・水まわり（冬季に向けた点検）", "inspect_m12": "・室内点検暖房の設定温度、室内換気", "inspect_m1": "・室内点検", "inspect_m2": "・通路（経路等）", "inspect_m3": "室内、室外遊具の安全点検", "daijiko_estab": "2025年12月1日", "daijiko_review": "2026年10月1日", "daijiko_place": "事務所内・更衣室", "m_nap_check": "○", "m_nap_estab": "2025年12月1日", "m_nap_review": "2026年10月1日", "m_nap_place": "各クラス iPad 内・事務所PC", "m_meal_check": "○", "m_meal_estab": "2025年12月1日", "m_meal_review": "2026年10月1日", "m_meal_place": "各クラス iPad 内・事務所 PC", "m_pool_check": "○", "m_pool_estab": "2025年12月1日", "m_pool_review": "2026年10月1日", "m_pool_place": "事務所内・更衣室", "m_outdoor_check": "○", "m_outdoor_estab": "2025年12月1日", "m_outdoor_review": "2026年10月1日", "m_outdoor_place": "事務所内・各クラス内", "saigai_estab": "2025年12月1日", "saigai_review": "2026年10月1日", "saigai_place": "事務所内・更衣室", "t119_estab": "2025年12月1日", "t119_review": "2026年10月1日", "t119_place": "事務所内・更衣室", "kyukyu_estab": "2025年12月1日", "kyukyu_review": "2026年10月1日", "kyukyu_place": "事務所内・更衣室", "fushinsha_estab": "2025年12月1日", "fushinsha_review": "2026年10月1日", "fushinsha_place": "事務所内・更衣室", "infant_term1": "・交通安全教室\n横断歩道は「右左右」手を挙げて渡る。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n\n遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n\n監視役と園児につく職員の役割を明確にする。\nプール遊び当日は、いつもより念入りに朝の視診を行う。\nプールに入れるとなっていても、実際に目で見て判断する。\n子どもの状態によっては、室内遊びや簡単な水遊び、時間を短めに設定するなどの対策をする。", "infant_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\n\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n\n冬の感染症には注意する。", "over3_term1": "・交通安全教室\n\n列の最前と最後尾の距離を空けずに歩く。\n歩道から降りないように指導。保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n横断歩道を渡る際は、「右見て左見て右見る」手を挙げて渡ることを指導する。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n\n早寝早起きをし朝ごはんをしっかり食べ、先生の話をよく聞き、お友だちを押したり走ったりしないようにする。", "over3_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\nバス乗車の約束\n\n\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n知らない人についていかない\nバスの中では立ち歩かない。大声で話さない。\n万が一車内に取り残された場合の危険性をこどもたちに伝えるとともに、緊急時には外部に助けを求めるための行動がとれるよう、こどもの発達に応じた支援を行う。\n（クラクション・バスの外に出る）", "guardian_term1": "・安全計画及び安全に関する取組の内容について、重要事項説明書として保護者に配布し、同意書を提出いただく。", "guardian_term2": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term3": "・安全計画及び安全に関する取組の内容について、玄関ホールに掲示し、周知を図る。\n・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term4": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "hinan_m4": "火災\n消火訓練\n避難訓練", "hinan_m5": "火災\n消火訓練\n避難訓練", "hinan_m6": "火災\n地震\n消火訓練\n避難訓練", "hinan_m7": "火災\n水害\n消火訓練\n避難訓練", "hinan_m8": "火災\n不審者訓練\n消火訓練\n避難訓練", "hinan_m9": "火災\n地震\n消火訓練\n避難訓練", "hinan_m10": "総合消防訓練\n地震\n消火訓練\n避難訓練", "hinan_m11": "火災\n消火訓練\n避難訓練", "hinan_m12": "火災\n不審者\n消火訓練\n避難訓練", "hinan_m1": "火災\n地震\n消火訓練\n避難訓練", "hinan_m2": "火災\n地震\n通報\n消火訓練\n避難訓練", "hinan_m3": "火災\n消火訓練\n避難訓練", "other_m4": "心肺蘇生法", "other_m6": "不審者訓練", "other_m8": "通報訓練", "other_m12": "不審者訓練", "other_m3": "通報訓練", "drill1_content": "消火訓練", "drill1_who": "訓練当日の出勤している職員", "staff_term1": "園外実施　保健安全研修\n園内実施　心肺蘇生", "staff_term2": "園内実施　心肺蘇生\n園外実施　障害児保育\n園外実施　乳児保育", "staff_term3": "園内実施　気道内異物除去", "staff_term4": "園外実施　保護者支援・子育て支援\n園外実施　幼児教育", "admin_schedule": "・救命講習1　事前学習必須・大和市消防本部で開催）\n・救命講習I　（大和市消防本部で開催）", "prevention": "・ヒヤリハット事例の園内研修\n・人数の点呼確認の実地訓練", "other": "・登降園管理システムを活用した安全管理\n・警察や消防等、地域の関係者と連携し研修や講習をしていただく。"}'::jsonb, 'draft');
  else
    update guidance_plans set content='{"inspect_m4": "・防火設備\n・避難経路\n・緊急連絡先", "inspect_m5": "・遊具\n・散歩コース（散歩コース内の固定遊具を含む。）", "inspect_m6": "・プール用具の安全点検", "inspect_m7": "・園庭全体（内扉、フェンス、固定遊具、排水路等）\n・園舎全体（水道、トイレ、建付け、高所等）", "inspect_m8": "・加湿器\n・空気清浄機", "inspect_m9": "・台風対策\n（備蓄の確認等）", "inspect_m10": "園外保育の危険か所の点検\n園外保育での歩き方の指導", "inspect_m11": "・水まわり（冬季に向けた点検）", "inspect_m12": "・室内点検暖房の設定温度、室内換気", "inspect_m1": "・室内点検", "inspect_m2": "・通路（経路等）", "inspect_m3": "室内、室外遊具の安全点検", "daijiko_estab": "2025年12月1日", "daijiko_review": "2026年10月1日", "daijiko_place": "事務所内・更衣室", "m_nap_check": "○", "m_nap_estab": "2025年12月1日", "m_nap_review": "2026年10月1日", "m_nap_place": "各クラス iPad 内・事務所PC", "m_meal_check": "○", "m_meal_estab": "2025年12月1日", "m_meal_review": "2026年10月1日", "m_meal_place": "各クラス iPad 内・事務所 PC", "m_pool_check": "○", "m_pool_estab": "2025年12月1日", "m_pool_review": "2026年10月1日", "m_pool_place": "事務所内・更衣室", "m_outdoor_check": "○", "m_outdoor_estab": "2025年12月1日", "m_outdoor_review": "2026年10月1日", "m_outdoor_place": "事務所内・各クラス内", "saigai_estab": "2025年12月1日", "saigai_review": "2026年10月1日", "saigai_place": "事務所内・更衣室", "t119_estab": "2025年12月1日", "t119_review": "2026年10月1日", "t119_place": "事務所内・更衣室", "kyukyu_estab": "2025年12月1日", "kyukyu_review": "2026年10月1日", "kyukyu_place": "事務所内・更衣室", "fushinsha_estab": "2025年12月1日", "fushinsha_review": "2026年10月1日", "fushinsha_place": "事務所内・更衣室", "infant_term1": "・交通安全教室\n横断歩道は「右左右」手を挙げて渡る。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n\n遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n\n監視役と園児につく職員の役割を明確にする。\nプール遊び当日は、いつもより念入りに朝の視診を行う。\nプールに入れるとなっていても、実際に目で見て判断する。\n子どもの状態によっては、室内遊びや簡単な水遊び、時間を短めに設定するなどの対策をする。", "infant_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "infant_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\n\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n\n冬の感染症には注意する。", "over3_term1": "・交通安全教室\n\n列の最前と最後尾の距離を空けずに歩く。\n歩道から降りないように指導。保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n横断歩道を渡る際は、「右見て左見て右見る」手を挙げて渡ることを指導する。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term2": "・熱中症対策\n水分補給・衣服の調節を行う\n・プール遊び時の事故防止\nプール活動ができる環境か\n・雨天、強風、雷が鳴ったとき\n・光化学スモッグ警報発令のとき\n・PM2.5の注意喚起のとき\n・暑さ（熱中症）指数が高いとき\n・土、砂等による汚染が著しいとき\n一つでも当てはまる場合は中止とする\n\n早寝早起きをし朝ごはんをしっかり食べ、先生の話をよく聞き、お友だちを押したり走ったりしないようにする。", "over3_term3": "・遊具遊びや散歩時の事故防止\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。", "over3_term4": "散歩時の歩き方指導\n冬休み中の安全で楽しい過ごし方\nバス乗車の約束\n\n\n戸外活動の際は、遊具の選択をし職員がつき安全に留意する\n列の最前と最後尾の距離を空けずに歩く。\n歩道から児童が降りないよう保育士は必ず歩道側を歩き歩道と逆側に園児がよって歩くように促す。\n信号待ちの際は、横断歩道（道路）からできる限り離れて待つ。\n信号を渡る際は、直進側の道路から右左折の車が入らないよう、保育士は直進側の道路に立つ。\n知らない人についていかない\nバスの中では立ち歩かない。大声で話さない。\n万が一車内に取り残された場合の危険性をこどもたちに伝えるとともに、緊急時には外部に助けを求めるための行動がとれるよう、こどもの発達に応じた支援を行う。\n（クラクション・バスの外に出る）", "guardian_term1": "・安全計画及び安全に関する取組の内容について、重要事項説明書として保護者に配布し、同意書を提出いただく。", "guardian_term2": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term3": "・安全計画及び安全に関する取組の内容について、玄関ホールに掲示し、周知を図る。\n・園だより（クラスだより）を活用し、取組内容の周知を図る。", "guardian_term4": "・園だより（クラスだより）を活用し、取組内容の周知を図る。", "hinan_m4": "火災\n消火訓練\n避難訓練", "hinan_m5": "火災\n消火訓練\n避難訓練", "hinan_m6": "火災\n地震\n消火訓練\n避難訓練", "hinan_m7": "火災\n水害\n消火訓練\n避難訓練", "hinan_m8": "火災\n不審者訓練\n消火訓練\n避難訓練", "hinan_m9": "火災\n地震\n消火訓練\n避難訓練", "hinan_m10": "総合消防訓練\n地震\n消火訓練\n避難訓練", "hinan_m11": "火災\n消火訓練\n避難訓練", "hinan_m12": "火災\n不審者\n消火訓練\n避難訓練", "hinan_m1": "火災\n地震\n消火訓練\n避難訓練", "hinan_m2": "火災\n地震\n通報\n消火訓練\n避難訓練", "hinan_m3": "火災\n消火訓練\n避難訓練", "other_m4": "心肺蘇生法", "other_m6": "不審者訓練", "other_m8": "通報訓練", "other_m12": "不審者訓練", "other_m3": "通報訓練", "drill1_content": "消火訓練", "drill1_who": "訓練当日の出勤している職員", "staff_term1": "園外実施　保健安全研修\n園内実施　心肺蘇生", "staff_term2": "園内実施　心肺蘇生\n園外実施　障害児保育\n園外実施　乳児保育", "staff_term3": "園内実施　気道内異物除去", "staff_term4": "園外実施　保護者支援・子育て支援\n園外実施　幼児教育", "admin_schedule": "・救命講習1　事前学習必須・大和市消防本部で開催）\n・救命講習I　（大和市消防本部で開催）", "prevention": "・ヒヤリハット事例の園内研修\n・人数の点呼確認の実地訓練", "other": "・登降園管理システムを活用した安全管理\n・警察や消防等、地域の関係者と連携し研修や講習をしていただく。"}'::jsonb where id=v_id;
  end if;
